// Verifies an HMAC over `timestamp + "." + canonicalJson(body)`.
// Canonical JSON (sorted keys, no spaces) is used because n8n receives parsed
// JSON, not the sender's original bytes — both sides must agree on one form.
// Requires NODE_FUNCTION_ALLOW_BUILTIN=crypto.
const crypto = require('crypto');

const secret = $env.LENDLOOP_SHARED_SECRET;
const input = $input.first().json;
const headers = input.headers ?? {};

const canonical = (value) => {
  if (value === null || typeof value !== 'object') return JSON.stringify(value) ?? 'null';
  if (Array.isArray(value)) return `[${value.map(canonical).join(',')}]`;
  const entries = Object.entries(value)
    .filter(([, entry]) => entry !== undefined)
    .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
  return `{${entries.map(([k, v]) => `${JSON.stringify(k)}:${canonical(v)}`).join(',')}}`;
};

const timestamp = String(headers['x-lendloop-timestamp'] ?? '');
const signature = String(headers['x-lendloop-signature'] ?? '');

const fail = (status, error) => [{ json: { status, body: { ok: false, error } } }];

if (!secret) return fail(503, 'LENDLOOP_SHARED_SECRET is not set on the n8n container');
if (!timestamp || !signature) return fail(401, 'Missing signature headers');

const skew = Math.abs(Date.now() - Number(timestamp) * 1000);
if (!Number.isFinite(skew) || skew > 5 * 60 * 1000) {
  return fail(401, 'Timestamp outside the five minute window');
}

let event;
try {
  event = typeof input.body === 'string' ? JSON.parse(input.body) : (input.body ?? {});
} catch {
  return fail(400, 'Body is not JSON');
}

const expected = crypto
  .createHmac('sha256', secret)
  .update(`${timestamp}.${canonical(event)}`)
  .digest('hex');

const valid =
  expected.length === signature.length &&
  crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(signature));

if (!valid) return fail(401, 'Invalid signature');

const data = event.data ?? {};
const forLender = event.kind === 'loan.requested';
const recipient = forLender ? data.ownerEmail : data.borrowerEmail;

const formatDay = (ms) => new Date(ms).toISOString().slice(0, 10);
const range = `${formatDay(data.startDate)} to ${formatDay(data.endDate)}`;

const subject = forLender
  ? `${data.borrowerName} wants to borrow your ${data.toolName}`
  : `Your request for ${data.toolName} was ${data.status}`;

const message = forLender
  ? `${data.borrowerName} asked for your ${data.toolName} (${range}). Approve or decline it in LendLoop.`
  : `The lender ${data.status} your request for ${data.toolName} (${range}).`;

// The assignment allows a logged mock notification instead of real email.
// Swap this for an Email/Slack node and the signature check above is unchanged.
console.log(`[LENDLOOP MOCK] to=${recipient ?? 'unknown'} subject=${subject} | ${message}`);

return [
  {
    json: {
      status: 200,
      body: {
        ok: true,
        audience: forLender ? 'lender' : 'borrower',
        eventId: event.eventId,
        to: recipient,
        subject,
        message,
      },
    },
  },
];
